/*
 * Hand-written MCP Events helpers. Not generated by Speakeasy: this file is not
 * tracked in .speakeasy/gen.lock, so it survives SDK regeneration.
 */

import * as z from "zod/v3";
import { McpEventsSource, McpResult } from "./client.js";
import { isPlainObject, JSONRPCError, resolveErrorCodes } from "./errors.js";
import {
  createMcpEventsHandlers,
  McpEventsHandlerOptions,
  McpEventsHandlers,
  McpEventsMethod,
} from "./handlers.js";

/** The low-level MCP `Server` methods used, in either SDK major. */
export type McpLowLevelServerLike = {
  setRequestHandler: (...args: any[]) => unknown;
  registerCapabilities: (capabilities: any) => unknown;
};

/** A low-level `Server`, or an `McpServer` wrapping one in `.server`. */
export type McpServerLike = McpLowLevelServerLike | { server: McpLowLevelServerLike };

export type RegisterMcpEventsOptions<Ctx = any> = McpEventsHandlerOptions<Ctx> & {
  /**
   * Returns the authenticated principal of an MCP request, for example the
   * OAuth subject from `ctx.http?.authInfo` (`@modelcontextprotocol/server`
   * v2) or `extra.authInfo` (`@modelcontextprotocol/sdk` 1.x). Never use the
   * OAuth client ID: every user of one MCP client shares it. A null,
   * undefined or empty result is rejected with Forbidden.
   */
  resolvePrincipal: (context: Ctx) => string | null | undefined | Promise<string | null | undefined>;
};

/** The extension identifier SEP-3415 advertises under `capabilities.extensions`. */
export const MCP_EVENTS_EXTENSION_ID = "io.modelcontextprotocol/events";

// `events: {}` is the design-sketch capability ChatGPT reads; the extensions
// entry is the SEP-3415 form. Advertising both is harmless to either client.
const EVENTS_CAPABILITIES = {
  events: {},
  extensions: { [MCP_EVENTS_EXTENSION_ID]: {} },
};

// A Standard Schema (v1) accepting any params object, for the v2 SDK's
// setRequestHandler(method, { params }, handler). Params are forwarded to
// Outpost untouched, which validates them.
const ANY_PARAMS_SCHEMA = {
  "~standard": {
    version: 1 as const,
    vendor: "outpost",
    validate: (value: unknown) =>
      isPlainObject(value)
        ? { value }
        : { issues: [{ message: "params must be an object" }] },
  },
};

const METHODS = ["events/list", "events/subscribe", "events/unsubscribe"] as const;

/**
 * Registers `events/list`, `events/subscribe` and `events/unsubscribe` on an
 * MCP server, proxied to Outpost, and declares the `events` capability.
 *
 * Call it before `connect()` (capabilities can't change afterwards), or
 * inside the per-request server factory of `createMcpHandler`. Targets
 * `@modelcontextprotocol/server` v2 (the SDK serving protocol revision
 * 2026-07-28, which ChatGPT requires) and falls back to the
 * `@modelcontextprotocol/sdk` 1.x API. Pass a low-level `Server` or an
 * `McpServer` (its `.server` is used).
 *
 * @param source An `Outpost` instance, `{ serverURL, apiKey }`, or an MCP
 *   Events client.
 */
export function registerMcpEvents<Ctx = any>(
  source: McpEventsSource,
  server: McpServerLike,
  options: RegisterMcpEventsOptions<Ctx>,
): McpEventsHandlers<Ctx> {
  if (typeof options?.resolvePrincipal !== "function") {
    throw new TypeError("resolvePrincipal is required");
  }
  const target = lowLevelServer(server);
  const handlers = createMcpEventsHandlers<Ctx>(source, options);
  const codes = resolveErrorCodes(options.codes);
  const { resolvePrincipal, onError } = options;

  const dispatch: Record<McpEventsMethod, McpEventsHandlers<Ctx>["handleList"]> = {
    "events/list": handlers.handleList,
    "events/subscribe": handlers.handleSubscribe,
    "events/unsubscribe": handlers.handleUnsubscribe,
  };

  const handle = async (
    method: McpEventsMethod,
    params: unknown,
    context: Ctx,
  ): Promise<McpResult> => {
    let principal: string | null | undefined;
    try {
      principal = await resolvePrincipal(context);
    } catch (err) {
      if (err instanceof JSONRPCError) {
        throw err;
      }
      if (onError) {
        try {
          onError(err, { method });
        } catch {
          // A logging hook must not change the answer.
        }
      }
      throw new JSONRPCError(codes.internalError, "Internal error");
    }
    return dispatch[method](principal, params, {
      context,
      signal: signalOf(context),
    });
  };

  // Capabilities first: it throws once connected, before any handler is set.
  target.registerCapabilities(EVENTS_CAPABILITIES);

  for (const method of METHODS) {
    registerHandler(target, method, handle);
  }
  return handlers;
}

function lowLevelServer(server: unknown): McpLowLevelServerLike {
  if (isLowLevelServer(server)) {
    return server;
  }
  if (typeof server === "object" && server !== null) {
    const inner = (server as Record<string, unknown>)["server"];
    if (isLowLevelServer(inner)) {
      return inner;
    }
  }
  throw new TypeError(
    "Expected an MCP Server or McpServer from @modelcontextprotocol/server or @modelcontextprotocol/sdk",
  );
}

function isLowLevelServer(value: unknown): value is McpLowLevelServerLike {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const v = value as Record<string, unknown>;
  return typeof v["setRequestHandler"] === "function"
    && typeof v["registerCapabilities"] === "function";
}

function registerHandler<Ctx>(
  server: McpLowLevelServerLike,
  method: McpEventsMethod,
  handle: (method: McpEventsMethod, params: unknown, context: Ctx) => Promise<McpResult>,
): void {
  let v2Error: unknown;
  try {
    // v2: custom methods take (method, { params }, (params, ctx) => result).
    // The 1.x signature throws on a string before registering anything.
    server.setRequestHandler(method, { params: ANY_PARAMS_SCHEMA }, (params: unknown, ctx: Ctx) =>
      handle(method, params, ctx));
    return;
  } catch (err) {
    v2Error = err;
  }
  try {
    // 1.x: a zod schema with the method literal, (request, extra) => result.
    const schema = z.object({ method: z.literal(method) }).passthrough();
    server.setRequestHandler(schema, (request: { params?: unknown }, extra: Ctx) =>
      handle(method, request.params, extra));
  } catch (v1Error) {
    throw new AggregateError(
      [v2Error, v1Error],
      `Could not register ${method}: unsupported MCP server`,
    );
  }
}

// v2 exposes the request's abort signal as ctx.mcpReq.signal, 1.x as extra.signal.
function signalOf(context: unknown): AbortSignal | undefined {
  if (typeof context !== "object" || context === null) {
    return undefined;
  }
  const c = context as Record<string, any>;
  const signal = c["mcpReq"]?.signal ?? c["signal"];
  return isAbortSignal(signal) ? signal : undefined;
}

function isAbortSignal(value: unknown): value is AbortSignal {
  return typeof value === "object"
    && value !== null
    && typeof (value as AbortSignal).addEventListener === "function"
    && typeof (value as AbortSignal).aborted === "boolean";
}
